:root {
  --bg-0: #050e14;
  --bg-1: #08161d;
  --bg-2: #0b2029;
  --panel: rgba(16, 34, 45, .88);
  --panel-2: rgba(11, 26, 36, .94);
  --panel-3: rgba(25, 48, 60, .72);
  --line: rgba(178, 235, 220, .12);
  --line-strong: rgba(178, 235, 220, .24);
  --cream: #fff6e3;
  --muted: #94adb1;
  --muted-2: #67858b;
  --mint: #75f2bb;
  --mint-2: #38d9b0;
  --teal: #42e8c6;
  --gold: #ffca6a;
