/* ═══ BOTTOM NAV / TABLET ═════════════════════════════════════════════════ */
.bottom-nav {
  display: none;
  flex: 0 0 auto;
  height: calc(62px + var(--safe-b));
  padding: 5px 8px calc(5px + var(--safe-b));
  background: linear-gradient(180deg, rgba(7, 19, 25, .97), rgba(5, 15, 21, .99));
  border-top: 1px solid var(--line);
  backdrop-filter: blur(20px);
  z-index: 30;
  position: relative;
}
.bottom-nav::before {
  content: '';
  position: absolute;
  left: 0; right: 0; top: -1px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(117, 242, 187, .25), transparent);
}
.bottom-link {
  flex: 1;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 2px;
  color: var(--muted-2);
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: .02em;
  position: relative;
  transition: color .2s;
  min-width: 0;
}
.bottom-link .bn-icon { width: 26px; height: 26px; display: grid; place-items: center; }
.bottom-link .bn-icon svg { width: 21px; height: 21px; }
.bottom-link.active { color: var(--mint); }
.bottom-link.active::after {
  content: '';
  position: absolute;
  top: -5px;
  width: 22px; height: 2px;
  border-radius: 99px;
  background: var(--mint);
  box-shadow: 0 0 10px rgba(117, 242, 187, .6);
}
.bottom-link-main { margin-top: -19px; }
.bottom-link-main .bn-icon {
  width: 50px; height: 50px;
  border-radius: 50%;
  background: linear-gradient(150deg, #c3ffe4 0%, #75f2bb 40%, #2dcb9f 100%);
  color: #05261e;
  border: 3px solid #08161d;
  box-shadow: 0 6px 20px rgba(56, 217, 176, .35), 0 0 0 1px rgba(117, 242, 187, .35), inset 0 1px 0 #fff;
}
.bottom-link-main .bn-icon svg { width: 25px; height: 25px; }
.bottom-link-main.active .bn-icon { box-shadow: 0 6px 26px rgba(56, 217, 176, .6), 0 0 0 3px rgba(117, 242, 187, .13), inset 0 1px 0 #fff; }
.bottom-link-main.active::after { display: none; }
.bottom-link-main span:last-child { margin-top: 1px; }

@media (max-width: 1180px) {
  .main-nav { display: none; }
  .bottom-nav { display: flex; }
  .topbar { gap: 14px; }
  .top-actions { margin-left: auto; }
  .toast-root { top: 80px; }
}
@media (max-width: 1020px) {
  .monster-grid { grid-template-columns: repeat(4, 1fr); }
  .home-grid { grid-template-columns: 1.15fr .85fr; }
  .home-hero { grid-template-columns: 1fr .9fr; }
}

