722:.reward-rays { position: absolute; inset: 0; background: conic-gradient(from 0deg, transparent 0deg, rgba(255, 213, 120, .06) 8deg, transparent 16deg, transparent 30deg, rgba(117, 242, 187, .05) 38deg, transparent 46deg); animation: slowSpin 40s linear infinite; pointer-events: none; }
723:.reward-kicker { position: relative; display: inline-block; font-size: 10px; letter-spacing: .3em; font-weight: 900; color: var(--gold); text-transform: uppercase; }
724:.reward-title { position: relative; font-family: var(--font-display); font-size: clamp(36px, 7vw, 54px); line-height: .9; font-weight: 800; margin-top: 5px; background: linear-gradient(120deg, #fff6d1, #ffca6a 50%, #ff9f4a); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 4px 20px rgba(255, 184, 77, .25)); }
725:.reward-sub { position: relative; color: var(--muted); font-size: 12px; font-weight: 700; margin-top: 7px; }
726:.reward-stars { position: relative; display: flex; justify-content: center; gap: 6px; margin-top: 10px; color: var(--gold); font-size: 24px; }
727:.reward-stars .star { animation: starPop .5s var(--ease-pop) both; filter: drop-shadow(0 0 8px rgba(255, 202, 106, .6)); }
729:.reward-grid { position: relative; display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; margin-top: 18px; text-align: left; }
730:.reward-item { display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 14px; background: rgba(255, 255, 255, .035); border: 1px solid var(--line); animation: rewardIn .45s var(--ease-pop) both; }
731:.reward-item:nth-child(2) { animation-delay: .07s; }
732:.reward-item:nth-child(3) { animation-delay: .14s; }
733:.reward-item:nth-child(4) { animation-delay: .21s; }
735:.reward-item .ri-icon { width: 34px; height: 34px; flex: 0 0 auto; border-radius: 10px; display: grid; place-items: center; background: rgba(255, 202, 106, .08); }
736:.reward-item .ri-icon .coin-icon { width: 18px; height: 18px; }
737:.reward-item .ri-icon .gem-icon { width: 16px; height: 18px; }
738:.reward-item .ri-icon svg { width: 18px; height: 18px; color: var(--gold); }
739:.reward-item .ri-copy span { display: block; font-size: 8px; letter-spacing: .12em; font-weight: 900; color: var(--muted-2); text-transform: uppercase; }
740:.reward-item .ri-copy b { font-family: var(--font-display); font-size: 17px; line-height: 1.1; }
741:.reward-egg { position: relative; margin-top: 16px; padding: 14px; border-radius: 18px; border: 1px dashed rgba(255, 202, 106, .3); background: rgba(255, 202, 106, .04); display: flex; align-items: center; gap: 13px; text-align: left; animation: rewardIn .5s .25s var(--ease-pop) both; }
742:.reward-egg .re-art { width: 62px; height: 62px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 14px; background: radial-gradient(circle, rgba(255, 202, 106, .15), transparent 70%); }
743:.reward-egg .re-art .monster-art { width: 70px; height: 70px; }
744:.reward-egg .re-copy span { font-size: 8px; letter-spacing: .14em; color: var(--gold); font-weight: 900; text-transform: uppercase; }
745:.reward-egg .re-copy b { display: block; font-family: var(--font-display); font-size: 18px; line-height: 1.05; }
746:.reward-egg .re-copy small { display: block; font-size: 10px; color: var(--muted); font-weight: 700; }
747:.reward-actions { position: relative; display: flex; gap: 8px; margin-top: 18px; }
748:.reward-actions .btn { flex: 1; }
750:.reward-close { position: absolute; top: 14px; right: 14px; z-index: 3; }

